from typing import List
import sys

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        sys.setrecursionlimit(10**6)
        n = len(nums)
        tree = [[] for _ in range(n)]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        total = sum(nums)

        def dfs(u: int, parent: int, target: int) -> int:
            """Return the sum left after partitioning the subtree into components of sum target."""
            cur = nums[u]
            for v in tree[u]:
                if v != parent:
                    cur += dfs(v, u, target)
            return cur if cur != target else 0

        for cand in range(1, total // 2 + 1):
            if total % cand != 0:
                continue
            if dfs(0, -1, cand) == 0:
                return total // cand
        return 0

