from collections import defaultdict

class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        # If k is zero or negative, every substring satisfies the condition
        if k <= 0:
            return len(s)
        return self.recursion(s, k)

    def recursion(self, s: str, k: int) -> int:
        if len(s) <= 1:
            return len(s)

        # Find the first character that appears less than k times
        for i, ch in enumerate(s):
            if s.count(ch) < k:
                # Split around this character and take the better side
                left = self.recursion(s[:i], k)
                right = self.recursion(s[i + 1:], k)
                return max(left, right)

        # All characters appear at least k times
        return len(s)

