from typing import List
import collections

class Solution:
    def invalidTransactions(self, transactions: List[str]) -> List[str]:
        invalid = []
        txn = collections.defaultdict(list)

        # Parse each transaction and store by name
        for trn in transactions:
            name, time_str, amount_str, city = trn.split(",")
            txn[name].append([int(time_str), int(amount_str), city])

        # Determine invalid transactions
        for i, trans in enumerate(transactions):
            name, time_str, amount_str, city = trans.split(",")
            amount = int(amount_str)
            time = int(time_str)

            # Rule 1: amount exceeds 1000
            if amount > 1000:
                invalid.append(trans)
            else:
                # Rule 2: another transaction of the same name within 60 minutes in a different city
                for t_time, _, t_city in txn[name]:
                    if city != t_city and abs(time - t_time) <= 60:
                        invalid.append(trans)
                        break

        return invalid

