from functools import lru_cache

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        n, m = len(word1), len(word2)

        @lru_cache(None)
        def rec(i: int, j: int) -> int:
            if i == n and j == m:
                return 0
            if i == n:
                return m - j
            if j == m:
                return n - i
            if word1[i] == word2[j]:
                # characters match → move both pointers forward (no operation)
                return rec(i + 1, j + 1)
            # try insert, delete, replace
            insert = 1 + rec(i, j + 1)
            delete = 1 + rec(i + 1, j)
            replace = 1 + rec(i + 1, j + 1)
            return min(insert, delete, replace)

        return rec(0, 0)

