        mid=(l+r)//2
        while l<r:
            if elegance(mid+1)>elegance(mid) or elegance(mid+1)==-1:
                l=mid+1
            else:
                r=mid
            mid=(l+r)//2
        return max(elegance(mid),elegance(mid+1))

