import collections

class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        # Record positions of each digit in s
        indexes = collections.defaultdict(collections.deque)
        for i, ch in enumerate(s):
            indexes[int(ch)].append(i)

        # Verify that we can build t respecting the ordering rule
        for ch in t:
            digit = int(ch)
            # Must have this digit available
            if digit not in indexes or not indexes[digit]:
                return False
            # No smaller digit may appear before the current one in s
            for smaller in range(digit):
                if indexes[smaller] and indexes[smaller][0] < indexes[digit][0]:
                    return False
            # Use up one occurrence of this digit
            indexes[digit].popleft()
            if not indexes[digit]:
                del indexes[digit]

        # All characters processed successfully
        return True

