from typing import List

class Solution:
    def isAlienSorted(self, words: List[str], order: str) -> bool:
        # map each character to its order index
        mapper = {c: -1 for c in "abcdefghijklmnopqrstuvwxyz"}
        for i, ch in enumerate(order):
            mapper[ch] = i

        def helper() -> bool:
            for i in range(len(words) - 1):
                w1, w2 = words[i], words[i + 1]
                # find first differing character
                j = 0
                while j < len(w1) and j < len(w2) and w1[j] == w2[j]:
                    j += 1
                if j < len(w1) and j < len(w2):
                    # characters differ, compare alien order
                    if mapper[w2[j]] < mapper[w1[j]]:
                        return False
                else:
                    # one word is a prefix of the other
                    if len(w1) > len(w2):
                        return False
            return True

        return helper()

