class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        from collections import defaultdict, deque
        idx = defaultdict(deque)
        for i, c in enumerate(s):
            idx[c].append(i)
        last = -1
        for c in t:
            if not idx[c]:
                return False
            while idx[c] and idx[c][0] <= last:
                idx[c].popleft()
            if not idx[c]:
                return False
            pos = idx[c].popleft()
            last = pos
        return True

